using EduCenterManagement.Services;using EduCenterManagement.Services.Common;using Microsoft.AspNetCore.Mvc;
namespace EduCenterManagement.Controllers;
// TEMP: no authentication yet. Replace QueryStringCurrentUserContext with claims-based implementation and add [Authorize] when auth is merged.
public sealed class ParentChildrenController(ICurrentUserContext current,IParentChildrenService service):Controller { public async Task<IActionResult> Index(CancellationToken ct){if(current.UserId is null)return View("NoUser");var m=await service.GetChildrenAsync(ct);if(m is null){ViewData["ProfileMessage"]="This user does not have a Parent profile.";return View("NoUser");}return View(m);} public async Task<IActionResult> Details(int studentId,CancellationToken ct){if(current.UserId is null)return View("NoUser");var m=await service.GetDetailsAsync(studentId,ct);return m is null?NotFound():View(m);} public async Task<IActionResult> Attendance(int studentId,int? classId,int page=1,CancellationToken ct=default){if(current.UserId is null)return View("NoUser");var m=await service.GetAttendanceAsync(studentId,classId,page,ct);return m is null?NotFound():View(m);} }
